local Players=game:GetService("Players") local UserInputService=game:GetService("UserInputService") local RunService=game:GetService("RunService") local TweenService=game:GetService("TweenService") local HttpService=game:GetService("HttpService") local LocalPlayer=Players.LocalPlayer local Character,RootPart,Humanoid local stopPlayback local currentConnections={} if _G.AldoKnightXorzV3_Cleanup then pcall(_G.AldoKnightXorzV3_Cleanup) end if _G.AldoKnightXorzV4_Cleanup then pcall(_G.AldoKnightXorzV4_Cleanup) end _G.AldoKnightXorzV4_Cleanup=function() for _,conn in ipairs(currentConnections) do if typeof(conn)=="RBXScriptConnection" then conn:Disconnect() end end currentConnections={} for _,name in ipairs({"AldoKnightXorzV3_Record","AldoKnightXorzV3_Playback","AldoKnightXorzV4_Record","AldoKnightXorzV4_Playback"}) do pcall(function() RunService:UnbindFromRenderStep(name) end) end local pg=LocalPlayer:FindFirstChildOfClass("PlayerGui") if pg then for _,gui in ipairs(pg:GetChildren()) do if gui:IsA("ScreenGui") and (gui.Name=="AldoKnightXorzV3Gui" or gui.Name=="AldoKnightXorzV4Gui" or gui.Name=="AldoKnightXorzV47Gui") then gui:Destroy() end end end end local function notify(title,text,duration) local ok=pcall(function() game:GetService("StarterGui"):SetCore("SendNotification",{Title=title,Text=text,Duration=duration}) end) return ok end local function setupCharacter(char) if stopPlayback then pcall(function() stopPlayback(true) end) end Character=char RootPart=char:WaitForChild("HumanoidRootPart") Humanoid=char:WaitForChild("Humanoid") if Humanoid then Humanoid.AutoRotate=true end end if LocalPlayer.Character then setupCharacter(LocalPlayer.Character) end table.insert(currentConnections,LocalPlayer.CharacterAdded:Connect(setupCharacter)) local _notifyGate=notify("🚶 AldoVZ Auto Walk","Loaded! Tap 🚶 to open",2) if not _notifyGate then return end local CFG={NodeInterval=0.04,MinDistance=0.1,LineColor=Color3.fromRGB(0,255,255),AccentColor=Color3.fromRGB(255,255,255),SaveFileName="ALDO_KNIGHTXORZ_PURE_V4_7.json"} local state={isRecording=false,isPlaying=false,isPaused=false,isAutoWalk=false,playbackID=0,timeline={},visualNodes={},lineVisible=true,selectedFile=1,savedFiles={},startTime=0,lastJumpState=false,movementSpeed=16,replayPrecision=true} local function normalizeTimeline(timeline) if #timeline==0 then return timeline end local baseTs=timeline[1].Timestamp for _,node in ipairs(timeline) do node.RelativeTimestamp=node.Timestamp-baseTs end return timeline end local function saveToDisk() local exportData={} for slot,data in pairs(state.savedFiles) do local encodedTimeline={} for _,node in ipairs(data.timeline) do table.insert(encodedTimeline,{P={math.round(node.Position.X100)/100,math.round(node.Position.Y100)/100,math.round(node.Position.Z100)/100},T=math.round(node.Timestamp1000)/1000,J=node.Jump}) end exportData[tostring(slot)]={timeline=encodedTimeline} end if writefile then pcall(function() writefile(CFG.SaveFileName,HttpService:JSONEncode(exportData)) end) end end local function loadFromDisk() if readfile then local success,result=pcall(function() return readfile(CFG.SaveFileName) end) if success and result then local ok,decoded=pcall(function() return HttpService:JSONDecode(result) end) if ok and type(decoded)=="table" then for slot,data in pairs(decoded) do if type(data)=="table" and type(data.timeline)=="table" then local decodedTimeline={} for _,node in ipairs(data.timeline) do if node.P then table.insert(decodedTimeline,{Position=Vector3.new(unpack(node.P)),Timestamp=node.T or 0,Jump=node.J or false}) end end state.savedFiles[tonumber(slot)]={timeline=normalizeTimeline(decodedTimeline)} end end end end end end loadFromDisk() local function getOrCreateRouteFolder() local folder=workspace:FindFirstChild("KNIGHTXORZ_ROUTE") if not folder then folder=Instance.new("Folder") folder.Name="KNIGHTXORZ_ROUTE" folder.Parent=workspace end return folder end local ScreenGui=Instance.new("ScreenGui") ScreenGui.Name="AldoKnightXorzV47Gui" ScreenGui.ResetOnSpawn=false ScreenGui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling ScreenGui.Parent=LocalPlayer:WaitForChild("PlayerGui") local OpenMenu=Instance.new("ImageButton") OpenMenu.Name="OpenMenu" OpenMenu.Size=UDim2.fromOffset(55,55) OpenMenu.Position=UDim2.new(0.05,0,0.5,0) OpenMenu.BackgroundTransparency=1 OpenMenu.Image="rbxassetid://101640388423900" OpenMenu.Parent=ScreenGui local OpenCorner=Instance.new("UICorner") OpenCorner.CornerRadius=UDim.new(0,8) OpenCorner.Parent=OpenMenu local OpenStroke=Instance.new("UIStroke") OpenStroke.Thickness=2 OpenStroke.Color=Color3.fromRGB(255,255,255) OpenStroke.Parent=OpenMenu local OpenGradient=Instance.new("UIGradient") OpenGradient.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.fromRGB(0,255,255)),ColorSequenceKeypoint.new(1,Color3.fromRGB(170,0,255))}) OpenGradient.Rotation=45 OpenGradient.Parent=OpenMenu task.spawn(function() while OpenMenu and OpenMenu.Parent do OpenGradient.Rotation+=1 task.wait(0.03) end end) local MainFrame=Instance.new("Frame") MainFrame.Name="MainFrame" MainFrame.Size=UDim2.new(0.65,0,0.45,0) MainFrame.AnchorPoint=Vector2.new(0.5,0.5) MainFrame.Position=UDim2.new(0.5,0,0.5,0) MainFrame.BackgroundColor3=Color3.fromRGB(10,10,15) MainFrame.BackgroundTransparency=0.2 MainFrame.BorderSizePixel=0 MainFrame.Active=true MainFrame.Visible=true MainFrame.Parent=ScreenGui local MainCorner=Instance.new("UICorner") MainCorner.CornerRadius=UDim.new(0,16) MainCorner.Parent=MainFrame local MainStroke=Instance.new("UIStroke") MainStroke.Thickness=2 MainStroke.Color=Color3.fromRGB(255,255,255) MainStroke.Transparency=0.3 MainStroke.Parent=MainFrame local MainGradient=Instance.new("UIGradient") MainGradient.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.fromRGB(40,40,50)),ColorSequenceKeypoint.new(1,Color3.fromRGB(10,10,15))}) MainGradient.Rotation=90 MainGradient.Parent=MainFrame local openMoved=false table.insert(currentConnections,OpenMenu.InputChanged:Connect(function(input) if input.UserInputType==Enum.UserInputType.Touch then openMoved=true end end)) table.insert(currentConnections,OpenMenu.MouseButton1Click:Connect(function() if openMoved then openMoved=false return end MainFrame.Visible=not MainFrame.Visible end)) local openDragging,openDragStart,openStartPos table.insert(currentConnections,OpenMenu.InputBegan:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then openDragging=true openDragStart=input.Position openStartPos=OpenMenu.Position openMoved=false local changedConn changedConn=input.Changed:Connect(function() if input.UserInputState==Enum.UserInputState.End then openDragging=false if changedConn then changedConn:Disconnect() end end end) end end)) table.insert(currentConnections,UserInputService.InputChanged:Connect(function(input) if openDragging and (input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch) then local delta=input.Position-openDragStart if delta.Magnitude>5 then openMoved=true end OpenMenu.Position=UDim2.new(openStartPos.X.Scale,openStartPos.X.Offset+delta.X,openStartPos.Y.Scale,openStartPos.Y.Offset+delta.Y) end end)) local Title=Instance.new("TextLabel") Title.Size=UDim2.new(1,0,0,35) Title.Text="ALDO KNIGHTXORZ V4.7" Title.TextColor3=Color3.fromRGB(255,255,255) Title.Font=Enum.Font.GothamBold Title.TextSize=14 Title.BackgroundTransparency=1 Title.Parent=MainFrame local StatusLabel=Instance.new("TextLabel") StatusLabel.Name="StatusLabel" StatusLabel.Size=UDim2.new(1,0,0,20) StatusLabel.Position=UDim2.fromOffset(0,30) StatusLabel.Text="Status: IDLE | File: 1" StatusLabel.TextColor3=Color3.fromRGB(0,255,255) StatusLabel.Font=Enum.Font.GothamBold StatusLabel.TextSize=11 StatusLabel.BackgroundTransparency=1 StatusLabel.Parent=MainFrame local ScrollingContainer=Instance.new("ScrollingFrame") ScrollingContainer.Size=UDim2.new(1,-16,1,-60) ScrollingContainer.Position=UDim2.fromOffset(8,55) ScrollingContainer.BackgroundTransparency=1 ScrollingContainer.BorderSizePixel=0 ScrollingContainer.CanvasSize=UDim2.new(0,0,0,650) ScrollingContainer.ScrollBarThickness=3 ScrollingContainer.Parent=MainFrame local UIList=Instance.new("UIListLayout") UIList.Parent=ScrollingContainer UIList.HorizontalAlignment=Enum.HorizontalAlignment.Center UIList.Padding=UDim.new(0,6) UIList.SortOrder=Enum.SortOrder.LayoutOrder local function updateStatus(text) if not ScreenGui or not ScreenGui.Parent then return end local lbl=ScreenGui:FindFirstChild("MainFrame") and ScreenGui.MainFrame:FindFirstChild("StatusLabel") if lbl then lbl.Text="Status: "..text.." | File: "..state.selectedFile end end local function createBtn(text,order,callback) local btn=Instance.new("TextButton") btn.Size=UDim2.fromOffset(240,32) btn.BackgroundColor3=Color3.fromRGB(25,25,35) btn.BackgroundTransparency=0.3 btn.Text=text btn.TextColor3=Color3.fromRGB(240,240,240) btn.Font=Enum.Font.GothamBold btn.TextSize=11 btn.LayoutOrder=order btn.Parent=ScrollingContainer local c=Instance.new("UICorner") c.CornerRadius=UDim.new(0,8) c.Parent=btn local s=Instance.new("UIStroke") s.Thickness=1 s.Color=Color3.fromRGB(255,255,255) s.Transparency=0.5 s.Parent=btn table.insert(currentConnections,btn.MouseButton1Click:Connect(function() TweenService:Create(btn,TweenInfo.new(0.15),{BackgroundColor3=Color3.fromRGB(0,255,255)}):Play() task.wait(0.15) TweenService:Create(btn,TweenInfo.new(0.15),{BackgroundColor3=Color3.fromRGB(25,25,35)}):Play() callback() end)) return btn end local function drawLine(p1,p2) local dist=(p1-p2).Magnitude if dist<0.01 then return end local folder=getOrCreateRouteFolder() local host=folder:FindFirstChild("BeamHost") if not host then host=Instance.new("Part") host.Name="BeamHost" host.Anchored=true host.CanCollide=false host.Transparency=1 host.Parent=folder end local att0=Instance.new("Attachment") att0.WorldPosition=p1 att0.Parent=host local att1=Instance.new("Attachment") att1.WorldPosition=p2 att1.Parent=host local beam=Instance.new("Beam") beam.Attachment0=att0 beam.Attachment1=att1 beam.Width0=0.25 beam.Width1=0.25 beam.FaceCamera=true beam.Color=ColorSequence.new(CFG.LineColor) beam.LightEmission=1 beam.LightInfluence=0 beam.Enabled=state.lineVisible beam.Parent=host table.insert(state.visualNodes,att0) table.insert(state.visualNodes,att1) table.insert(state.visualNodes,beam) end local function clearVisuals() for _,v in ipairs(state.visualNodes) do if v then v:Destroy() end end state.visualNodes={} local folder=workspace:FindFirstChild("KNIGHTXORZ_ROUTE") if folder then folder:ClearAllChildren() end end RunService:BindToRenderStep("AldoKnightXorzV4_Record",Enum.RenderPriority.Character.Value,function() if not state.isRecording or not RootPart or not Humanoid then return end local pos=RootPart.Position local st=Humanoid:GetState() local vel=RootPart.AssemblyLinearVelocity local currentTimestamp=tick()-state.startTime local isJumping=(Humanoid.FloorMaterial==Enum.Material.Air and vel.Y>1) or st==Enum.HumanoidStateType.Jumping or (st==Enum.HumanoidStateType.Freefall and vel.Y>2) local jumpTrigger=isJumping and not state.lastJumpState state.lastJumpState=isJumping if #state.timeline==0 then table.insert(state.timeline,{Position=pos,Timestamp=currentTimestamp,Jump=jumpTrigger}) else local lastNode=state.timeline[#state.timeline] local dist=(pos-lastNode.Position).Magnitude local timeDiff=currentTimestamp-lastNode.Timestamp if (timeDiff>=CFG.NodeInterval and dist>=CFG.MinDistance) or jumpTrigger then drawLine(lastNode.Position,pos) table.insert(state.timeline,{Position=pos,Timestamp=currentTimestamp,Jump=jumpTrigger}) end end end) stopPlayback=function(manualStop) state.isPlaying=false state.isPaused=false state.playbackID+=1 if manualStop then state.isAutoWalk=false end pcall(function() RunService:UnbindFromRenderStep("AldoKnightXorzV4_Playback") end) if Humanoid then Humanoid.AutoRotate=true Humanoid:Move(Vector3.zero,true) end updateStatus("IDLE") end local function executePlayback() if #state.timeline<2 or state.isPlaying or not RootPart or not Humanoid then return end stopPlayback(false) state.isPlaying=true state.isPaused=false state.playbackID+=1 local currentPlaybackID=state.playbackID Humanoid.WalkSpeed=state.movementSpeed local playbackState="WALKING_TO_START" local startPos=state.timeline[1].Position local playbackStartTime=0 local pauseOffset=0 local currentIndex=1 local stuckTimer=0 local lastCheckPos=RootPart.Position local stuckJumpCooldown=0 local timeoutTimer=tick()+25 updateStatus("WALKING TO START") RunService:BindToRenderStep("AldoKnightXorzV4_Playback",Enum.RenderPriority.Last.Value,function(dt) if not state.isPlaying or state.playbackID~=currentPlaybackID or not RootPart or not Humanoid then stopPlayback(false) return end if state.isPaused then pauseOffset+=dt Humanoid:Move(Vector3.zero,true) return end if playbackState=="WALKING_TO_START" or playbackState=="RETURNING_TO_START" then local currentPos=RootPart.Position local dirToStart=startPos-currentPos local horizDist=Vector3.new(dirToStart.X,0,dirToStart.Z).Magnitude if horizDist>1.2 and tick()<=timeoutTimer then Humanoid.AutoRotate=true Humanoid:Move(Vector3.new(dirToStart.X,0,dirToStart.Z).Unit,false) else playbackState="PLAYING" playbackStartTime=tick() pauseOffset=0 currentIndex=1 lastCheckPos=RootPart.Position stuckTimer=0 stuckJumpCooldown=0 updateStatus(state.isAutoWalk and "AUTO WALK" or "PLAYING") end elseif playbackState=="PLAYING" then local currentTime=tick()-playbackStartTime-pauseOffset while currentIndex<#state.timeline and currentTime>=state.timeline[currentIndex+1].RelativeTimestamp do currentIndex+=1 end if currentIndex>=#state.timeline then if state.isAutoWalk then playbackState="RETURNING_TO_START" timeoutTimer=tick()+25 updateStatus("WALKING TO START") else stopPlayback(false) end return end local targetNode=state.timeline[currentIndex+1] or state.timeline[currentIndex] local currentPos=RootPart.Position local direction=targetNode.Position-currentPos local horizontal=Vector3.new(direction.X,0,direction.Z) if targetNode.Jump and horizontal.Magnitude<1.8 then Humanoid.Jump=true Humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end if (currentPos-lastCheckPos).Magnitude<0.04 and horizontal.Magnitude>0.2 then stuckTimer+=dt if stuckTimer>2 and tick()-stuckJumpCooldown>2.5 then Humanoid.Jump=true Humanoid:ChangeState(Enum.HumanoidStateType.Jumping) stuckJumpCooldown=tick() stuckTimer=0 end else stuckTimer=0 lastCheckPos=currentPos end if horizontal.Magnitude>0.1 then Humanoid.AutoRotate=true Humanoid:Move(horizontal.Unit,false) if direction.Y>1.5 then Humanoid.Jump=true end end end end) end local function toggleAutoWalk() if state.isRecording then return end state.isAutoWalk=not state.isAutoWalk if state.isAutoWalk then updateStatus("AUTO WALK") if not state.isPlaying then executePlayback() end else stopPlayback(true) end end createBtn("RECORD START / STOP",1,function() state.isRecording=not state.isRecording if state.isRecording then stopPlayback(true) state.timeline={} clearVisuals() state.startTime=tick() state.lastJumpState=false updateStatus("RECORDING") else normalizeTimeline(state.timeline) updateStatus("IDLE") end end) createBtn("PLAY ROUTE",2,function() if state.isRecording then return end state.isAutoWalk=false executePlayback() end) createBtn("PAUSE / RESUME",3,function() if not state.isPlaying then return end state.isPaused=not state.isPaused if state.isPaused then updateStatus("PAUSED") else updateStatus(state.isAutoWalk and "AUTO WALK" or "PLAYING") end end) createBtn("AUTO WALK ON / OFF",4,function() toggleAutoWalk() end) createBtn("STOP PLAYBACK",5,function() stopPlayback(true) end) for i=1,5 do createBtn("SELECT FILE "..i,5+i,function() state.selectedFile=i updateStatus("IDLE") end) end createBtn("SAVE FILE",11,function() if #state.timeline>0 then normalizeTimeline(state.timeline) state.savedFiles[state.selectedFile]={timeline=state.timeline} saveToDisk() updateStatus("SAVED FILE "..state.selectedFile) end end) createBtn("LOAD FILE",12,function() local fileData=state.savedFiles[state.selectedFile] if fileData and fileData.timeline then stopPlayback(true) state.timeline=normalizeTimeline(fileData.timeline) clearVisuals() for i=2,#state.timeline do drawLine(state.timeline[i-1].Position,state.timeline[i].Position) end updateStatus("LOADED FILE "..state.selectedFile) end end) createBtn("CLEAR ROUTE",13,function() stopPlayback(true) state.timeline={} clearVisuals() updateStatus("CLEARED") end) createBtn("SHOW / HIDE LINE",14,function() state.lineVisible=not state.lineVisible local folder=workspace:FindFirstChild("KNIGHTXORZ_ROUTE") if folder then local host=folder:FindFirstChild("BeamHost") if host then for _,child in ipairs(host:GetChildren()) do if child:IsA("Beam") then child.Enabled=state.lineVisible end end end end end)
